src='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    squares = []
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1] == 2:
                squares.append((r, c))
    for r, c in squares:
        corners = [(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
        if not all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] not in (0,2) for rr,cc in corners):
            continue
        tl, tr, bl, br = [grid[rr][cc] for rr,cc in corners]
        rays = [(corners[0], bl, -1,-1),(corners[1],tl,-1,1),
                (corners[2],br,1,-1),(corners[3],tr,1,1)]
        for (rr,cc), color, dr, dc in rays:
            first = True
            while 0 <= rr < h and 0 <= cc < w:
                if first:
                    out[rr][cc] = color
                    first = False
                elif out[rr][cc] == 0:
                    out[rr][cc] = color
                rr += dr
                cc += dc
    return out
